"""Validation against the schemas generated by ``packages/contract``."""

from __future__ import annotations

import json
from functools import cached_property
from pathlib import Path
from typing import Any

from jsonschema import Draft202012Validator

from .errors import InvalidParams, UnknownMethod

_SCHEMA_FILE = Path(__file__).parent.parent / "contract" / "rpc.schema.json"


class Contract:
    def __init__(self, schema_file: Path = _SCHEMA_FILE) -> None:
        self._schema_file = schema_file

    @cached_property
    def _document(self) -> dict[str, Any]:
        return json.loads(self._schema_file.read_text(encoding="utf-8"))

    @cached_property
    def _validators(self) -> dict[str, tuple[Draft202012Validator, Draft202012Validator]]:
        return {
            name: (Draft202012Validator(method["params"]), Draft202012Validator(method["result"]))
            for name, method in self._document["methods"].items()
        }

    @property
    def method_names(self) -> set[str]:
        return set(self._document["methods"])

    @property
    def grid(self) -> dict[str, Any]:
        """The dashboard grid, shared with the web app: columns, sizes and default layout."""
        return self._document["grid"]

    @property
    def default_settings(self) -> dict[str, Any]:
        return self._document["defaultSettings"]

    @property
    def ai(self) -> dict[str, Any]:
        """Providers, the settings an AI may touch and the tools it can use."""
        return self._document["ai"]

    def check_params(self, method: str, params: Any) -> None:
        validator = self._validator(method)[0]
        error = next(validator.iter_errors(params), None)
        if error is not None:
            raise InvalidParams(error.message)

    def check_result(self, method: str, result: Any) -> None:
        validator = self._validator(method)[1]
        error = next(validator.iter_errors(result), None)
        if error is not None:
            raise ValueError(f"{method} returned an invalid result: {error.message}")

    def _validator(self, method: str) -> tuple[Draft202012Validator, Draft202012Validator]:
        try:
            return self._validators[method]
        except KeyError:
            raise UnknownMethod(f"Unknown method: {method}") from None
